import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

site_response = session.post(
    f"{BASE_URL}/sites/add",
    json={"name": "New Mining Site"},
)
site_response.raise_for_status()
site = site_response.json()
site_id = site.get("siteId", site.get("id"))

status_response = session.get(f"{BASE_URL}/equipment-status")
status_response.raise_for_status()
status_data = status_response.json()

equipment = status_data if isinstance(status_data, list) else status_data.get(
    "equipment", status_data.get("machinery", [])
)

for item in equipment:
    if not isinstance(item, dict):
        continue
    equipment_id = item.get("id", item.get("equipmentId"))
    if equipment_id is None:
        continue
    session.post(
        f"{BASE_URL}/equipment/maintenance-schedule",
        json={
            "equipmentId": equipment_id,
            "siteId": site_id,
            "schedule": "Maintenance scheduled for operational equipment",
        },
    ).raise_for_status()

materials_response = session.get(f"{BASE_URL}/projects/{site_id}/materials")
materials_response.raise_for_status()
project_materials_data = materials_response.json()
project_materials = (
    project_materials_data
    if isinstance(project_materials_data, list)
    else project_materials_data.get("materials", [])
)

inventory_response = session.get(f"{BASE_URL}/inventory/status")
inventory_response.raise_for_status()
inventory_data = inventory_response.json()
inventory_items = (
    inventory_data
    if isinstance(inventory_data, list)
    else inventory_data.get("materials", inventory_data.get("inventory", []))
)

project_material_ids = {
    str(material.get("id", material.get("materialId")))
    for material in project_materials
    if isinstance(material, dict)
    and material.get("id", material.get("materialId")) is not None
}

for item in inventory_items:
    if not isinstance(item, dict):
        continue
    obsolete = item.get("obsolete") is True or str(item.get("status", "")).lower() == "obsolete"
    material_id = item.get("materialId", item.get("id"))
    if obsolete and material_id is not None:
        session.delete(
            f"{BASE_URL}/inventory/material/{material_id}"
        ).raise_for_status()

report_response = session.post(
    f"{BASE_URL}/reports/generate",
    json={
        "siteId": site_id,
        "include": [
            "regulatory updates",
            "current operational status of machinery",
        ],
        "operationalStatus": status_data,
    },
)
