import os
import requests

BASE_URL = os.getenv("SOCBENCH_API_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

def get(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", **kwargs)
    response.raise_for_status()
    return response.json()

def post(path, payload):
    response = session.post(
        f"{BASE_URL}{path}",
        json=payload,
        headers={"Content-Type": "application/json"},
    )
    response.raise_for_status()
    return response.json() if response.content else None

# Inventory and threat review
equipment = get("/equipment")
threats = get("/threats")

# Compare threat details with equipment records to identify potential risks.
# The API documentation does not define equipment or threat fields, nor does it
# provide a vulnerability-scanning endpoint, so only explicit matches can be used.
def searchable_text(record):
    if isinstance(record, dict):
        return " ".join(str(value) for value in record.values()).lower()
    return str(record).lower()

threat_text = [searchable_text(threat) for threat in threats]
at_risk_equipment = []
for item in equipment:
    item_text = searchable_text(item)
    if any(
        token in item_text and token in threat
        for threat in threat_text
        for token in item_text.split()
        if len(token) > 3
    ):
        at_risk_equipment.append(item)

# No documented vulnerability-to-patch mapping or software schema is provided.
# Avoid inventing patch records; retrieve installed software for review.
software = get("/software")

# Review available scaling strategies and resource usage where resource IDs are
# present in the documented analytics response.
strategies = get("/optimization-strategies")
analytics = get("/analytics/stats")
resource_ids = set()
def collect_resource_ids(value):
    if isinstance(value, dict):
        for key, item in value.items():
            if key.lower() in {"resource_id", "resourceid"} and item is not None:
                resource_ids.add(str(item))
            else:
                collect_resource_ids(item)
    elif isinstance(value, list):
        for item in value:
            collect_resource_ids(item)

collect_resource_ids(analytics)
resource_usage = {
    resource_id: get(f"/resource-usage/{resource_id}")
    for resource_id in resource_ids
}

# Scaling requires a ScaleRequest schema and resource identifiers; neither is
# specified sufficiently to safely initiate scaling operations.
tracking = get("/tracking/assets")

results = {
    "equipment": equipment,
    "threats": threats,
    "potentially_at_risk_equipment": at_risk_equipment,
    "installed_software": software,
    "optimization_strategies": strategies,
    "analytics": analytics,
    "resource_usage": resource_usage,
    "real_time_tracking": tracking,
}

